    for (int j = 0; j <= lt; j++) d[0][j] = j;

    for (int i = 1; i <= ls; i++) {
        for (int j = 1; j <= lt; j++) {
            int cost = (s[i-1] == t[j-1]) ? 0 : 1;
            d[i][j] = min3(d[i-1][j] + 1, d[i][j-1] + 1, d[i-1][j-1] + cost);
            if (i > 1 && j > 1 && s[i-1] == t[j-2] && s[i-2] == t[j-1]) {
