#include <string.h>

#define MAXN 205
#define MAXL 105
#define INF 1000000000

typedef struct {
    char a[MAXL];
    char b[MAXL];
} Pair;

static int min4(int a, int b, int c, int d) {
    int m = a < b ? a : b;
    if (c < m) m = c;
    if (d < m) m = d;
    return m;
}

static int cmpstr(const void *p1, const void *p2) {
    const char *a = (const char *)p1;
    const char *b = (const char *)p2;
    return strcmp(a, b);
}

static int cmppair(const void *p1, const void *p2) {
    const Pair *x = (const Pair *)p1;
    const Pair *y = (const Pair *)p2;
    int t = strcmp(x->a, y->a);
    if (t != 0) return t;
    return strcmp(x->b, y->b);
}

/* Damerau-Levenshtein distance with adjacent transposition, bounded by limit */
static int distance_bounded(const char *s, const char *t, int limit) {
    int n = (int)strlen(s);
    int m = (int)strlen(t);

    if (abs(n - m) > limit) return limit + 1;

    static int dp[MAXL][MAXL];
    for (int i = 0; i <= n; i++) dp[i][0] = i;
    for (int j = 0; j <= m; j++) dp[0][j] = j;

    for (int i = 1; i <= n; i++) {
        int rowMin = INF;
        for (int j = 1; j <= m; j++) {
            int cost = (s[i - 1] == t[j - 1]) ? 0 : 1;
            int del = dp[i - 1][j] + 1;
            int ins = dp[i][j - 1] + 1;
            int rep = dp[i - 1][j - 1] + cost;
            int trn = INF;

            if (i >= 2 && j >= 2 &&
                s[i - 1] == t[j - 2] &&
                s[i - 2] == t[j - 1]) {
                trn = dp[i - 2][j - 2] + 1;
            }

            dp[i][j] = min4(del, ins, rep, trn);
            if (dp[i][j] < rowMin) rowMin = dp[i][j];
        }
        if (rowMin > limit) return limit + 1;
    }
    return dp[n][m];
}

int main(void) {
    int n, d;
    int dataset = 1;

    while (scanf("%d %d", &n, &d) == 2) {
        if (n == 0 && d == 0) break;

        char names[MAXN][MAXL];
        for (int i = 0; i < n; i++) {
            scanf("%s", names[i]);
        }

        qsort(names, n, sizeof(names[0]), cmpstr);

        Pair *pairs = (Pair *)malloc((size_t)n * (n - 1) / 2 * sizeof(Pair));
        int pcnt = 0;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int dist = distance_bounded(names[i], names[j], d);
                if (dist <= d) {
                    strcpy(pairs[pcnt].a, names[i]);
                    strcpy(pairs[pcnt].b, names[j]);
                    pcnt++;
                }
            }
        }

        qsort(pairs, pcnt, sizeof(Pair), cmppair);

        printf("Case %d\n", dataset++);
