#include <bits/stdc++.h>
using namespace std;

/*
  Damerau-Levenshtein distance with adjacent transposition, bounded by K.
  We only need to know whether distance <= K, so we use a banded DP and
  stop early when possible.

  dp[i][j] = min edits to transform a[0..i) -> b[0..j)
  allowed ops:
    - delete
    - insert
    - replace
    - swap adjacent characters
*/

static const int INF = 1e9;

bool withinDistance(const string& a, const string& b, int K) {
    int n = (int)a.size();
    int m = (int)b.size();

    if (abs(n - m) > K) return false;

    // Full DP is fine for typical contest constraints, but we keep it banded.
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, INF));
    dp[0][0] = 0;

    for (int i = 0; i <= n; ++i) {
        int jL = max(0, i - K);
        int jR = min(m, i + K);

        int rowMin = INF;
        for (int j = jL; j <= jR; ++j) {
            if (i == 0 && j == 0) {
                rowMin = min(rowMin, dp[i][j]);
                continue;
            }

            int best = INF;

            if (i > 0 && abs((i - 1) - j) <= K)
                best = min(best, dp[i - 1][j] + 1); // delete

            if (j > 0 && abs(i - (j - 1)) <= K)
                best = min(best, dp[i][j - 1] + 1); // insert

            if (i > 0 && j > 0 && abs((i - 1) - (j - 1)) <= K)
                best = min(best, dp[i - 1][j - 1] + (a[i - 1] == b[j - 1] ? 0 : 1)); // replace/match

            if (i > 1 && j > 1 &&
                a[i - 1] == b[j - 2] &&
                a[i - 2] == b[j - 1] &&
                abs((i - 2) - (j - 2)) <= K) {
                best = min(best, dp[i - 2][j - 2] + 1); // adjacent swap
            }

            dp[i][j] = best;
            rowMin = min(rowMin, best);
        }

        if (rowMin > K) return false;
    }

    return dp[n][m] <= K;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, K;
    bool firstCase = true;

    while (cin >> n >> K) {
        if (n == 0 && K == 0) break;

        vector<string> names(n);
