        vector<pair<string, string>> ans;

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (withinDistance(names[i], names[j], K)) {
                    ans.push_back({names[i], names[j]});
                }
            }
        }

        if (!firstCase) cout << '\n';
        firstCase = false;

        for (auto &p : ans) {
            cout << p.first << "," << p.second << '\n';
        }
        cout << ans.size() << '\n';
    }

    return 0;
}

