import java.io.*;
import java.util.*;

/*
 * Confusing login names:
 * For each dataset, given n names and threshold d, output all pairs (a,b), a<b,
 * whose Damerau-Levenshtein distance (insert, delete, replace, swap adjacent) <= d.
 *
 * Output pairs in alphabetical order, then the total count.
 *
 * Since the original statement snippet does not specify exact input/output wording,
 * this solution assumes datasets are given as:
 *
 * t
 * n d
 * name1
 * name2
 * ...
 * namen
 * ...
 *
 * If there is no leading t, it also supports EOF-style:
 * n d
 * name1
 * ...
 * namen
 * ...
 *
 * Output format used:
 * Data Set k:
 * a b
 * ...
 * Count: X
 *
 * with a blank line between datasets.
 */
public class Main {

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static int damerauLevenshtein(String a, String b, int limit) {
        int n = a.length();
        int m = b.length();

        if (Math.abs(n - m) > limit) return limit + 1;

        int[][] dp = new int[n + 1][m + 1];

        for (int i = 0; i <= n; i++) dp[i][0] = i;
        for (int j = 0; j <= m; j++) dp[0][j] = j;

        for (int i = 1; i <= n; i++) {
            int rowMin = Integer.MAX_VALUE;
            char ca = a.charAt(i - 1);
            for (int j = 1; j <= m; j++) {
                char cb = b.charAt(j - 1);

                int cost = (ca == cb) ? 0 : 1;

                int best = Math.min(
                        Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1),
                        dp[i - 1][j - 1] + cost
                );

                if (i > 1 && j > 1
                        && a.charAt(i - 1) == b.charAt(j - 2)
                        && a.charAt(i - 2) == b.charAt(j - 1)) {
                    best = Math.min(best, dp[i - 2][j - 2] + 1);
                }

                dp[i][j] = best;
                rowMin = Math.min(rowMin, best);
            }
            if (rowMin > limit) return limit + 1;
        }

        return dp[n][m];
    }

    static class Pair implements Comparable<Pair> {
        String a, b;
        Pair(String x, String y) {
            if (x.compareTo(y) <= 0) {
                a = x; b = y;
            } else {
                a = y; b = x;
            }
        }

        @Override
        public int compareTo(Pair o) {
            int c = a.compareTo(o.a);
            if (c != 0) return c;
            return b.compareTo(o.b);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        List<String> tokens = new ArrayList<>();
        while (true) {
            String s = fs.next();
            if (s == null) break;
            tokens.add(s);
        }
        if (tokens.isEmpty()) return;

        StringBuilder out = new StringBuilder();

        int idx = 0;
        int datasets;

        // Try to interpret first token as number of datasets.
        boolean hasLeadingT = false;
        try {
            int t = Integer.parseInt(tokens.get(0));
            int tmp = 1;
            boolean ok = true;
            for (int ds = 0; ds < t; ds++) {
                if (tmp + 1 >= tokens.size()) {
                    ok = false;
                    break;
                }
                int n = Integer.parseInt(tokens.get(tmp));
                Integer.parseInt(tokens.get(tmp + 1));
                tmp += 2;
                if (tmp + n > tokens.size()) {
                    ok = false;
                    break;
                }
                tmp += n;
            }
            if (ok && tmp == tokens.size()) {
                hasLeadingT = true;
                datasets = t;
                idx = 1;
            } else {
                datasets = -1;
            }
        } catch (Exception e) {
            datasets = -1;
        }

        int dsNum = 1;
        if (hasLeadingT) {
            for (int ds = 0; ds < datasets; ds++) {
                int n = Integer.parseInt(tokens.get(idx++));
                int limit = Integer.parseInt(tokens.get(idx++));
                String[] names = new String[n];
                for (int i = 0; i < n; i++) names[i] = tokens.get(idx++);

                List<Pair> ans = solve(names, limit);

                if (ds > 0) out.append('\n');
                out.append("Data Set ").append(dsNum++).append(":\n");
                for (Pair p : ans) out.append(p.a).append(' ').append(p.b).append('\n');
                out.append("Count: ").append(ans.size()).append('\n');
            }
        } else {
            boolean first = true;
            while (idx < tokens.size()) {
                int n = Integer.parseInt(tokens.get(idx++));
                int limit = Integer.parseInt(tokens.get(idx++));
                String[] names = new String[n];
                for (int i = 0; i < n; i++) names[i] = tokens.get(idx++);

                List<Pair> ans = solve(names, limit);

                if (!first) out.append('\n');
                first = false;
                out.append("Data Set ").append(dsNum++).append(":\n");
                for (Pair p : ans) out.append(p.a).append(' ').append(p.b).append('\n');
                out.append("Count: ").append(ans.size()).append('\n');
            }
        }

        System.out.print(out.toString());
    }

    static List<Pair> solve(String[] names, int limit) {
        String[] sorted = names.clone();
        Arrays.sort(sorted);

        List<Pair> ans = new ArrayList<>();
        int n = sorted.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (damerauLevenshtein(sorted[i], sorted[j], limit) <= limit) {
                    ans.add(new Pair(sorted[i], sorted[j]));
                }
            }
        }
        Collections.sort(ans);
        return ans;
    }
}

