                dp[i][j - 1] + 1,
                dp[i - 1][j - 1] + cost
            )
            if i > 1 and j > 1 and s1[i - 1] == s2[j - 2] and s1[i - 2] == s2[j - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 2][j - 2] + cost)
    return dp[n][m]

def solve():
    data = sys.stdin.read().strip().splitlines()
    idx = 0
    first = True
    while idx < len(data):
        if data[idx] == '':
            idx += 1
            continue
        parts = data[idx].split()
        if len(parts) < 2:
            idx += 1
            continue
        n = int(parts[0])
        t = int(parts[1])
        idx += 1
        names = []
        for _ in range(n):
            if idx < len(data):
                names.append(data[idx].strip())
                idx += 1
        pairs = []
        for i in range(n):
            for j in range(i + 1, n):
                dist = levenshtein_with_swap(names[i], names[j])
                if dist <= t:
                    pair = sorted([names[i], names[j]])
                    pairs.append((pair[0], pair[1]))
        pairs.sort()
        if not first:
            print()
        first = False
        for a, b in pairs:
            print(f"{a},{b}")
        print(len(pairs))

if __name__ == "__main__":
    solve()
